from __future__ import annotations

import argparse
import importlib
import inspect
import re
from collections import defaultdict
from collections.abc import Iterator
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from modal_dojo.common import models
from modal_dojo.common.models.base import ModelConfig

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_README = ROOT / "README.md"
BEGIN_MARKER = "<!-- BEGIN MODELS LIST -->"
END_MARKER = "<!-- END MODELS LIST -->"
BANNER = (
    "<!-- Auto-generated by scripts/generate_models_table.py from the recipe "
    "registries in modal_dojo/train_recipes/*/__init__.py. -->"
)
FRAMEWORKS = (
    "modal_dojo.train_recipes.slime_recipe",
    "modal_dojo.train_recipes.miles_recipe",
)
BASE_RECIPES = {"SlimeRecipe", "MilesRecipe"}
FRAMEWORK_BASES = frozenset({*BASE_RECIPES, "MilesConfig"})
MODEL_CONFIGS = {name.lower(): getattr(models, name) for name in models.__all__}
FAMILY_RE = re.compile(r"^([A-Za-z]+(?:\d+(?:\.\d+)*|\d+)?)")
HF_URL = "https://huggingface.co"
DOCS_URL = "https://dojo.modal.dev"
TUTORIALS = {"Qwen/Qwen3-ASR-1.7B": "audio_asr"}


@dataclass(frozen=True)
class RecipeRow:
    hf_id: str
    config: str
    recipe: str
    framework: str
    method: str
    context: str
    response: str
    gpus: str

    @property
    def display_name(self) -> str:
        return self.hf_id.rsplit("/", 1)[-1]

    @property
    def slug(self) -> str:
        return re.sub(r"[^a-z0-9]+", "-", self.recipe.removesuffix("_Recipe").lower())


@dataclass(frozen=True)
class FamilyRow:
    family: str
    rows: tuple[RecipeRow, ...]


def model_key(recipe_name: str) -> str:
    return recipe_name.split("_Recipe")[0].removesuffix("_LoRA").lower()


def family_of(hf_id: str) -> str:
    slug = hf_id.rsplit("/", 1)[-1]
    match = FAMILY_RE.match(slug)
    family = match.group(1) if match else slug
    return family.title() if family.islower() else family


def tokens(n: int | None) -> str:
    if not n:
        return "—"
    return f"{n // 1024}K" if n % 1024 == 0 else str(n)


def recipe_row(
    hf_id: str, config: str, name: str, recipe: Any, module_path: str
) -> RecipeRow:
    r = recipe()
    lora_rank = getattr(r, "lora_rank", None)
    gpus = f"{r.actor_num_nodes}×{r.actor_num_gpus_per_node} {r.gpu_type}"
    if not r.colocate and r.rollout_num_gpus:
        gpus += f" + {r.rollout_num_gpus} rollout"
    return RecipeRow(
        hf_id=hf_id,
        config=config,
        recipe=name,
        framework=module_path.rsplit(".", 1)[-1].removesuffix("_recipe").title(),
        method=f"LoRA r{lora_rank}" if lora_rank else "Full",
        context=tokens(
            getattr(r, "seq_length", None)
            or getattr(r, "rollout_max_context_len", None)
        ),
        response=tokens(r.rollout_max_response_len),
        gpus=gpus,
    )


def iter_registered_recipes() -> Iterator[tuple[str, Any, Any, str]]:
    for module_path in FRAMEWORKS:
        registry = importlib.import_module(module_path)
        for recipe_name in registry.__all__:
            if recipe_name in BASE_RECIPES:
                continue
            recipe = getattr(registry, recipe_name)
            config = recipe.model_config_class or MODEL_CONFIGS.get(
                model_key(recipe_name)
            )
            yield recipe_name, recipe, config, module_path


def _is_preset_class(obj: Any, name: str) -> bool:
    if name in FRAMEWORK_BASES or not inspect.isclass(obj):
        return False
    module = obj.__module__
    if issubclass(obj, ModelConfig):
        return "common.models" in module and not module.endswith(".base")
    return "train_recipes" in module


def collect_model_preset_names() -> frozenset[str]:
    names: set[str] = set()
    for recipe_name, _recipe, config, _module_path in iter_registered_recipes():
        names.add(recipe_name)
        if config is not None:
            names.add(config.__name__)
    for name in models.__all__:
        if _is_preset_class(getattr(models, name), name):
            names.add(name)
    return frozenset(names)


def collect_models() -> tuple[FamilyRow, ...]:
    families: dict[str, list[RecipeRow]] = defaultdict(list)
    unmatched: list[str] = []
    for recipe_name, recipe, config, module_path in iter_registered_recipes():
        model_name = getattr(config, "model_name", None)
        if not model_name:
            unmatched.append(f"{module_path}.{recipe_name}")
            continue
        families[family_of(model_name)].append(
            recipe_row(model_name, config.__name__, recipe_name, recipe, module_path)
        )
    if unmatched:
        raise SystemExit(
            "No ModelConfig found for these recipes:\n  "
            + "\n  ".join(unmatched)
            + "\nSet model_config_class on the recipe, or export a matching "
            "ModelConfig from modal_dojo.common.models."
        )
    return tuple(
        FamilyRow(
            family=family,
            rows=tuple(sorted(rows, key=lambda r: (r.display_name, r.recipe))),
        )
        for family, rows in sorted(families.items())
    )


def render_snippet(row: RecipeRow) -> list[str]:
    tutorial = TUTORIALS.get(row.hf_id)
    if tutorial:
        return [
            f"See the [{tutorial} tutorial]({DOCS_URL}/tutorials/{tutorial}) "
            "for a runnable example.",
        ]
    return [
        "```python",
        "from modal_dojo import (",
        "    HuggingFaceDataset,",
        "    TrainConfig,",
        f"    {row.config},",
        f"    {row.recipe},",
        ")",
        "",
        "config = TrainConfig(",
        f"    model={row.config}(),",
        "    dataset=HuggingFaceDataset(",
        '        hf_repo="zhuzilin/dapo-math-17k",',
        '        input_column="prompt",',
        '        output_column="label",',
        '        input_format="messages",',
        "    ),",
        f'    recipe={row.recipe}(rm_type="deepscaler"),',
        ")",
        "",
        'if __name__ == "__main__":',
        "    run = config.launch()",
        "    print(run.training_run_id)",
        "```",
    ]


def render_row(family: str, row: RecipeRow) -> list[str]:
    cells = [
        family,
        f'<a href="{HF_URL}/{row.hf_id}">{row.display_name}</a>',
        row.framework,
        row.method,
        row.context,
        row.response,
        row.gpus,
    ]
    return [
        f'<tr class="model-row" data-model="{row.slug}">'
        + "".join(f"<td>{cell}</td>" for cell in cells)
        + "</tr>",
        f'<tr class="model-code"><td colspan="{len(cells)}">',
        f'<details id="model-{row.slug}" data-model="{row.slug}">',
        f"<summary>Run {row.recipe}</summary>",
        "",
        *render_snippet(row),
        "",
        "</details>",
        "</td></tr>",
    ]


def render_section(families: tuple[FamilyRow, ...]) -> str:
    header = "".join(
        f"<th>{h}</th>"
        for h in (
            "Family",
            "Model",
            "Framework",
            "Training",
            "Context",
            "Max response",
            "GPUs",
        )
    )
    body: list[str] = []
    for family in families:
        for i, row in enumerate(family.rows):
            body.extend(render_row(family.family if i == 0 else "", row))
    return "\n".join(
        [
            BEGIN_MARKER,
            BANNER,
            "",
            "Click a row for a runnable snippet. Link to one with "
            f"`{DOCS_URL}/?model=<name>`, e.g. `?model=beam`.",
            "",
            "<table>",
            f"<thead><tr>{header}</tr></thead>",
            "<tbody>",
            *body,
            "</tbody>",
            "</table>",
            END_MARKER,
        ]
    )


def rendered_readme(
    readme_path: Path, families: tuple[FamilyRow, ...]
) -> tuple[str, str]:
    content = readme_path.read_text()
    if BEGIN_MARKER not in content or END_MARKER not in content:
        raise SystemExit(
            f"Markers {BEGIN_MARKER} / {END_MARKER} not found in {readme_path}"
        )
    before, rest = content.split(BEGIN_MARKER, 1)
    _, after = rest.split(END_MARKER, 1)
    return content, f"{before}{render_section(families)}{after}"


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Generate the Family | Models table in README.md."
    )
    parser.add_argument("--readme", type=Path, default=DEFAULT_README)
    parser.add_argument(
        "--check",
        action="store_true",
        help="Exit non-zero if the model table is out of date.",
    )
    args = parser.parse_args()
    families = collect_models()
    current, updated = rendered_readme(args.readme, families)
    count = len({row.hf_id for family in families for row in family.rows})
    if args.check:
        if current != updated:
            raise SystemExit(
                f"{args.readme} model table is out of date. Run "
                "uv run scripts/generate_models_table.py"
            )
        print(f"Model table is up to date ({count} models)")
        return
    if current != updated:
        args.readme.write_text(updated)
    print(f"Wrote model table ({count} models)")


if __name__ == "__main__":
    main()
